 const sp=IMG.sp1,s2=IMG.sp2;if(ok(sp)){const n=Math.max(1,Math.round(f.W/3)),sw=Math.min(f.W/n*1.5,5)*Z;for(let i=0;i<n;i++){const ph=tt*3+i*1.7,sc=1+.08*Math.sin(ph),xx=X(f.x-f.W/2+(i+.5)*f.W/n);g.globalAlpha=.9;g.drawImage(sp,xx-sw*sc/2,yb-sw*.55*sc,sw*sc,sw*.7*sc)}}
