/* V2: mặt vách dài – ghép cột từ 4 mẫu vd1…vd4 ở mật độ gốc, lặp ngang theo toạ độ thế giới (liền mạch giữa các đoạn) */
const CTL=new Map();
function cliffTile(H){const Hp=Math.round(H*PXM);let c=CTL.get(Hp);if(c)return c;const ims=['vd1','vd2','vd3','vd4'].map(k=>IMG[k]);if(!ims.every(ok))return null;
 let W=0;const cols=ims.map(im=>{const v=fitV(im,0,im.naturalWidth,Hp);const w=Math.round(im.naturalWidth*.62);W+=w;return[v,w]});
 c=document.createElement('canvas');c.width=W;c.height=Hp;const g=c.getContext('2d');g.imageSmoothingEnabled=false;let x=0;for(const[v,w]of cols){g.drawImage(v,x-6,0);x+=w}CTL.set(Hp,c);return c}
const WTL=new Map();function wallTile(H){const Hp=Math.round(H*PXM);let c=WTL.get(Hp);if(c)return c;c=document.createElement('canvas');c.width=128;c.height=Hp;const g=c.getContext('2d'),R=rng(4242);
 g.fillStyle='#8e8a80';g.fillRect(0,0,128,Hp);const top=Math.round(PXM*.9);
 for(let y=top,row=0;y<Hp;y+=12,row++)for(let x=-(row%2)*12;x<128;x+=24){const v=(R()-.5)*26;g.fillStyle='rgb('+[150+v,145+v,134+v].map(q=>q|0)+')';g.fillRect(x+1,y+1,22,10);g.fillStyle='rgba(255,255,255,.12)';g.fillRect(x+1,y+1,22,2)}
 g.fillStyle='#6f6b62';for(let x=0;x<128;x+=16)g.fillRect(x,0,10,top);g.fillStyle='rgba(0,0,0,.18)';g.fillRect(0,top-2,128,2);
 const gr=g.createLinearGradient(0,0,0,Hp);gr.addColorStop(0,'rgba(0,0,0,0)');gr.addColorStop(1,'rgba(30,25,20,.35)');g.fillStyle=gr;g.fillRect(0,0,128,Hp);WTL.set(Hp,c);return c}
function cliffStrip(c){if(c.cv)return c.cv;const t=c.wall?wallTile(c.H):cliffTile(c.H);if(!t)return null;const Wp=Math.max(1,Math.round((c.x1-c.x0)*PXM)),cv=document.createElement('canvas');cv.width=Wp;cv.height=t.height;const g=cv.getContext('2d');g.imageSmoothingEnabled=false;
 let x=0,sx=((Math.round(c.x0*PXM)%t.width)+t.width)%t.width;while(x<Wp){const sw=Math.min(t.width-sx,Wp-x);g.drawImage(t,sx,0,sw,t.height,x,0,sw,t.height);x+=sw;sx=0}
 g.globalCompositeOperation='source-atop';const gr=g.createLinearGradient(0,0,0,t.height);gr.addColorStop(0,'rgba(255,255,255,.06)');gr.addColorStop(1,'rgba(0,0,0,.18)');g.fillStyle=gr;g.fillRect(0,0,Wp,t.height);c.cv=cv;return cv}
function drawCliff(g,c,X,Y,Z){const cv=cliffStrip(c);if(!cv)return;const k=Z*PX/(cv.s||1),yb=Y(c.yb);g.save();g.imageSmoothingEnabled=false;g.drawImage(cv,X(c.x0),yb-cv.height*k,(c.x1-c.x0)*Z,cv.height*k);g.restore()}
