function drawWet(g,x,y,Z,st,t,mv){const pm=pat(g,'w_md'),hgt=[0,.18,.42,.68][st]*Z*1.75,w=Z*.95;g.save();if(pm){const ww=w*.5;g.beginPath();g.ellipse(x,y-Z*.02,ww,Z*.16,0,0,7);g.rect(x-ww,y-hgt,ww*2,hgt);g.ellipse(x,y-hgt,ww,Z*.11,0,0,7);g.clip();setPat(pm,Z*PX,0,0,Z*PX,x,y+t/1000*Z*.3);g.fillStyle=pm;g.globalAlpha=st==1?.5:.82;g.fillRect(x-w,y-hgt-Z*.12,w*2,hgt+Z*.32);}g.restore();
 g.save();g.strokeStyle='rgba(235,248,255,.75)';g.lineWidth=Math.max(1,Z*.04);const ph=(t/600)%1;for(let k=0;k<(mv?3:1);k++){const p=(ph+k/3)%1;g.globalAlpha=(1-p)*(mv?.9:.5);g.beginPath();g.ellipse(x,y-hgt+Z*.05,w*(.45+p*.6),Z*(.12+p*.15),0,0,7);g.stroke()}g.restore()}
