 g.lineCap=g.lineJoin='round';g.strokeStyle='#3a8fd0';for(const r of RV){g.lineWidth=Math.max(lw*1.2,r.HW[0]*2*K);g.beginPath();for(let i=0;i<r.N;i+=3)i?g.lineTo(X(r.X[i]),Y(r.Y[i])):g.moveTo(X(r.X[i]),Y(r.Y[i]));g.lineTo(X(r.X[r.N-1]),Y(r.Y[r.N-1]));g.stroke()}
 g.strokeStyle='#7a5a3a';g.lineWidth=Math.max(lw*1.4,2.5*K);for(const c of CLF)if(!c.wall){g.beginPath();g.moveTo(X(c.x0),Y(c.yb));g.lineTo(X(c.x1),Y(c.yb));g.stroke()}
