 const sig=ZV2.map(z=>z.open?1:0).join('')+(W15.noLock?'n':'')+'|'+SH.ZN.map(z=>z.r.join(',')+(z.g||'')).join(';')+'|'+(globalThis.TERRAIN8?TERRAIN8.signature:'');if(MC.c&&Math.abs(pos.x-MC.ax)<300&&Math.abs(pos.y-MC.ay)<300&&sig==MC.sig)return MC;
 const RR=600,PX=Math.round(2*RR*k*2);if(!MC.c){MC.c=document.createElement('canvas');MC.c.width=MC.c.height=PX}const g=MC.c.getContext('2d');MC.ax=Math.round(pos.x);MC.ay=Math.round(pos.y);MC.sig=sig;MC.n++;
 const ax=MC.ax,ay=MC.ay,X=x=>(x-ax)*k+RR*k,Y=y=>(y-ay)*k+RR*k;g.setTransform(2,0,0,2,0,0);g.fillStyle='#4e7f3a';g.fillRect(0,0,PX,PX);
