 const hRiver=(x,y,i,ri)=>{let h=.3+.3*hsh2(i>>3,ri,21);for(const{f,pl}of M8S.FS){const d=Math.min(Math.hypot(x-f.x,y-f.lip),Math.hypot(x-f.x,y-f.base),pl?Math.max(0,Math.hypot(x-pl.x,(y-pl.y)/pl.ry)-pl.r):1e9);const k=clamp(1-(d-6)/26,0,1);h+=(1.25+.35*hsh2(i>>2,ri,22)-h)*k*k*(3-2*k)}return h};
